-- Preçário real da BarberShop AOS (Mercado Central de Bissau): 24 serviços em 3 categorias.
-- Corre isto UMA vez no Supabase > SQL Editor (Run). Pode ser corrido outra vez sem estragar nada.
-- Atenção: troca a lista de serviços que está no painel (as fotos de serviços que tenhas posto no painel perdem-se).
-- Cada serviço: n = nome, p = preço, d = duração em minutos (estimativa: ajusta no painel), c = categoria,
-- g = grupo dentro da categoria, mais = "ou mais" (preço a partir de), dom = serviço ao domicílio (pede a morada).
update public.settings
set services = $json$[{"n":"Corte","p":2500,"d":30,"c":"Cabelo"},{"n":"Corte liso","p":3000,"d":45,"c":"Cabelo"},{"n":"Tratamento de Waves","p":3000,"d":30,"c":"Cabelo"},{"n":"Alinhar contornos (zona comum)","p":1500,"d":15,"c":"Cabelo"},{"n":"Barba","p":1500,"d":30,"c":"Cabelo"},{"n":"Caracóis","p":1500,"d":30,"c":"Cabelo"},{"n":"Afro","p":5000,"d":60,"c":"Cabelo"},{"n":"Contornos com aerógrafo","p":500,"d":15,"c":"Pintura","g":"Aerógrafo"},{"n":"Cabelo de barba em preto","p":1000,"d":30,"c":"Pintura","g":"Preto"},{"n":"Cabelo a Pente 1 em preto","p":1000,"d":30,"c":"Pintura","g":"Preto"},{"n":"Cabelo até Pente 4 em preto","p":2000,"d":45,"c":"Pintura","g":"Preto"},{"n":"Cabelo superior a Pente 4 em preto","p":3000,"d":60,"c":"Pintura","g":"Preto","mais":true},{"n":"Cabelo a Pente 1 em amarelo queimado","p":4000,"d":60,"c":"Pintura","g":"Amarelo queimado"},{"n":"Cabelo até Pente 4 em amarelo queimado","p":6000,"d":90,"c":"Pintura","g":"Amarelo queimado"},{"n":"Cabelo superior a Pente 4 em amarelo queimado","p":7500,"d":120,"c":"Pintura","g":"Amarelo queimado","mais":true},{"n":"Cabelo a Pente 1 a branco","p":5000,"d":60,"c":"Pintura","g":"Branco"},{"n":"Cabelo até Pente 4 a branco","p":7000,"d":90,"c":"Pintura","g":"Branco"},{"n":"Cabelo superior a Pente 4 a branco","p":10000,"d":120,"c":"Pintura","g":"Branco","mais":true},{"n":"Cabelo a Pente 1 em outras cores disponíveis","p":7500,"d":60,"c":"Pintura","g":"Outras cores"},{"n":"Cabelo até Pente 4 em outras cores disponíveis","p":10000,"d":90,"c":"Pintura","g":"Outras cores"},{"n":"Cabelo superior a Pente 4 em outras cores disponíveis","p":12000,"d":120,"c":"Pintura","g":"Outras cores","mais":true},{"n":"Em Bissau, até à zona antes do Aeroporto","p":7500,"d":60,"c":"Domicílio","dom":true},{"n":"Entre Quelelé e Gardete","p":10000,"d":60,"c":"Domicílio","dom":true},{"n":"Entre o Aeroporto e Safim/Bissalanca","p":10000,"d":60,"c":"Domicílio","mais":true,"dom":true}]$json$::jsonb
where id = 1;
